------------ lifeCycle ------------

function CustomTrainrewardPreviewPopup:__init()
    self:CleanProperties()
    self.selectIndex = 1
    self.areaId = 0
    self.rewardGroup = 0
    self.Config = {}
end

function CustomTrainrewardPreviewPopup:__delete()
    self:CleanProperties()
end

function CustomTrainrewardPreviewPopup:Awake()
end

function CustomTrainrewardPreviewPopup:OnInitialize()
    xTry(function()
        ---@type CustomTrainComponent 
        local CustomTrainComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CustomTrainComponent)
        local questVos = CustomTrainComponent:GetCustomTrainQuestVosByGroupId(CustomTrainComponent:GetDojo().schedule.groupId)
        for i, v in ipairs(questVos) do
            self.Config[#self.Config+1] = { text = v.name ,  areaId =  v.areaId , rewardGroup = v.rewardGroup }
        end
        self.areaId = checkInt(self.controller.Argument.parameters.areaId) 
        self.rewardGroup = checkInt(self.controller.Argument.parameters.rewardGroup) 
        self:GetRewardData()
        self:FreshToggleTab()
        self:LoopModeFreshRewardCellList(#self.rewardData[tostring(self.rewardGroup)])
        self:InitComponent()
    end)
end
---FreshToggleTab
---刷新顶部的标签信息
function CustomTrainrewardPreviewPopup:FreshToggleTab()
	local toggleData = {}
	local config = checkTable(self.Config)
    local openType = 1
	for i, v in pairs(config) do
        if checkInt(v.areaId)  == self.areaId then
            openType = i 
        end
		table.insert(toggleData,{
			index = checkNumber(i),
			text = v.text,
			checkFunc = function()
				return true
			end,
			func = function(index)
                self.areaId = self.Config[index].areaId
                self.rewardGroup = self.Config[index].rewardGroup
                self:LoopModeFreshRewardCellList(#self.rewardData[tostring(self.rewardGroup)])
			end
		})
	end
	self._toggleData = toggleData
	---@type CommonTabToggleUp
	local env = CfUtils.GetLuaScr(self.CommonTabToggleUp.gameObject, CommonTabToggleUpEnvPath)
	if isNull(env) then return end
	env:FillToggles(self._toggleData, openType)
	--end
end

function CustomTrainrewardPreviewPopup:OnShow()
    xTry(function()
        GameUtils.HidePreviousDialogs(self.controller)
    end)
end

function CustomTrainrewardPreviewPopup:OnFocus(focus)
end

function CustomTrainrewardPreviewPopup:OnFinalize()
    xTry(function()
        GameUtils.ShowPreviousDialogs(self.controller)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end)
end

