function CustomTrainrewardPreviewPopup:CleanProperties()
    self.rewardData = nil
    self.systemName = nil
    self.component = nil
    self.Config = nil
    self.rewardGroup = nil
end

function CustomTrainrewardPreviewPopup:InitComponent()
    local closeCallback = Bind(self, self.OnCloseBtn)
    SetButtonAction(self.Btn_Close, closeCallback)
    SetButtonAction(self.BtnClose, closeCallback)
    UIEventProxy.Create(self.Btn_Bg.gameObject).onPointerClick = closeCallback
end

function CustomTrainrewardPreviewPopup:OnCloseBtn()
    UIModule.BackDialog()
end

function CustomTrainrewardPreviewPopup:LoopModeFreshRewardCellList(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function CustomTrainrewardPreviewPopup:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local cell = loopListView:NewListViewItem("Cell")
    local LB_cell = GetLuaBehaviour(cell.gameObject, RewardCellLuaPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        LB_cell:Init()
    end
    local LT_cell = LB_cell.Env
    LT_cell:SetPanelInfo(self.rewardData[tostring(self.rewardGroup)][index+1])
    return cell
end

function CustomTrainrewardPreviewPopup:GetRewardData()
    self.rewardData = {}        -- 全部奖励数组
    ---@type CustomTrainPersonHurtVo[]
    local allData = CfUtils.GetCf(AutoIds.IdSetting8944, RewardVo, true)
    for i, v in ipairs(allData) do
        if not self.rewardData[tostring(v.rewardGroup)] then
            self.rewardData[tostring(v.rewardGroup)] = {}
        end
        table.insert(self.rewardData[tostring(v.rewardGroup)], v)
    end
end

return CustomTrainrewardPreviewPopup


